 if(argc!=4)throw std::runtime_error("MODEL ACTUAL_TINY_FIXTURE OUT");const std::filesystem::path out=argv[3];if(std::filesystem::exists(out))throw std::runtime_error("immutable exact-memo test output exists");auto model=JointEventModel::load(argv[1]);const auto fixture=eventio::read_json(argv[2]);JointObservation selected;bool found=false;std::size_t fixture_index=0;
